const VARIANT: u32 = 2u;
// The working-space (linear Display P3) <-> sRGB conversion, rendered by
// filtrate-core's build script from `space/constants.rs`, the one
// definition of these numbers on the CPU and the GPU.

// Linear Display P3 to linear sRGB (both D65), columns first.
const SPACE_P3_TO_SRGB: mat3x3<f32> = mat3x3<f32>(
    vec3<f32>(1.2249401807785034, -0.042056918144226074, -0.019637584686279297),
    vec3<f32>(-0.22494018077850342, 1.042056918144226, -0.0786360502243042),
    vec3<f32>(-0.0, 0.0, 1.0982736349105835),
);

// Linear sRGB to linear Display P3 (both D65), columns first.
const SPACE_SRGB_TO_P3: mat3x3<f32> = mat3x3<f32>(
    vec3<f32>(0.8224619626998901, 0.03319418430328369, 0.017082631587982178),
    vec3<f32>(0.17753803730010986, 0.9668058156967163, 0.07239741086959839),
    vec3<f32>(0.0, -0.0, 0.9105199575424194),
);

// The sRGB transfer (IEC 61966-2-1).
const SPACE_SRGB_SLOPE: f32 = 12.920000076293945;
const SPACE_SRGB_OFFSET: f32 = 0.054999999701976776;
const SPACE_SRGB_SCALE: f32 = 1.0549999475479126;
const SPACE_SRGB_GAMMA: f32 = 2.4000000953674316;
const SPACE_SRGB_INVERSE_GAMMA: f32 = 0.4166666567325592;
const SPACE_SRGB_LINEAR_BREAK: f32 = 0.0031308000907301903;
const SPACE_SRGB_ENCODED_BREAK: f32 = 0.040449999272823334;

// The sRGB transfer of linear channels, mirrored through zero so extended
// values stay extended.
fn space_srgb_encode(linear: vec3<f32>) -> vec3<f32> {
    let magnitude = abs(linear);
    let curve = select(
        magnitude * SPACE_SRGB_SLOPE,
        SPACE_SRGB_SCALE * pow(magnitude, vec3<f32>(SPACE_SRGB_INVERSE_GAMMA)) - SPACE_SRGB_OFFSET,
        magnitude > vec3<f32>(SPACE_SRGB_LINEAR_BREAK),
    );
    return sign(linear) * curve;
}

// The inverse of `space_srgb_encode`.
fn space_srgb_decode(encoded: vec3<f32>) -> vec3<f32> {
    let magnitude = abs(encoded);
    let curve = select(
        magnitude / SPACE_SRGB_SLOPE,
        pow((magnitude + SPACE_SRGB_OFFSET) / SPACE_SRGB_SCALE, vec3<f32>(SPACE_SRGB_GAMMA)),
        magnitude > vec3<f32>(SPACE_SRGB_ENCODED_BREAK),
    );
    return sign(encoded) * curve;
}

// Premultiplied working-space colour to premultiplied sRGB. A pixel with
// zero alpha carries no colour and becomes transparent black.
fn space_to_srgb(color: vec4<f32>) -> vec4<f32> {
    if color.a == 0.0 {
        return vec4<f32>(0.0);
    }
    let straight = color.rgb / color.a;
    return vec4<f32>(space_srgb_encode(SPACE_P3_TO_SRGB * straight) * color.a, color.a);
}

// Premultiplied sRGB to premultiplied working-space colour, the inverse of
// `space_to_srgb`.
fn space_from_srgb(color: vec4<f32>) -> vec4<f32> {
    if color.a == 0.0 {
        return vec4<f32>(0.0);
    }
    let straight = color.rgb / color.a;
    return vec4<f32>(SPACE_SRGB_TO_P3 * space_srgb_decode(straight) * color.a, color.a);
}
// Shared engine module prelude: the instanced-quad machinery every fixed
// pipeline builds on — instance layout, vertex stage, SDF coverage and the
// clip/mask coverage helper. `build.rs` concatenates this file ahead of the
// engine tail (`shader.wgsl`) and the external-frame tail (`external.wgsl`);
// it is not a module on its own.
//
// Layouts here mirror `render::instance` on the CPU side exactly.

const KIND_FILL: u32 = 0u;
const KIND_STROKE_OFFSET: u32 = 1u; // coverage(outer shape) - coverage(inner shape)
const KIND_STROKE_DIST: u32 = 2u;   // coverage(d - hw) - coverage(d + hw)
const KIND_SHADOW: u32 = 3u;        // Gaussian-blurred rounded box
const KIND_GLYPH: u32 = 4u;         // coverage from the glyph atlas
const KIND_SPAN: u32 = 5u;          // a full-coverage device-space run
const KIND_REGION: u32 = 6u;        // atlas cell with a retained full interval
const KIND_POLYGON: u32 = 7u;       // appended opaque interior tier (opaque phase only)

const PAINT_SOLID: u32 = 0u;
const PAINT_LINEAR: u32 = 1u;
const PAINT_RADIAL: u32 = 2u;
const PAINT_TEXTURE: u32 = 3u;      // composite: sample the bound texture at the device pixel
const PAINT_SWEEP: u32 = 4u;
const PAINT_IMAGE: u32 = 5u;
const PAINT_MESH: u32 = 6u;
const PAINT_BACKDROP: u32 = 7u;   // member composite with a per-member effect

const EFFECT_COLOR: u32 = 1u;
const EFFECT_REFRACTION: u32 = 2u;
const EFFECT_SHADER: u32 = 3u;
const EFFECT_RIM: u32 = 4u;
const EFFECT_SAMPLE: u32 = 5u;
const EFFECT_LEVEL: u32 = 6u;

const EXTEND_PAD: u32 = 0u;
const EXTEND_REPEAT: u32 = 1u;
const EXTEND_REFLECT: u32 = 2u;
const EXTEND_NONE: u32 = 3u;

const INTERP_WORKING: u32 = 0u;
const INTERP_SRGB: u32 = 1u;

const FLAG_HAS_CLIP: u32 = 1u;
const FLAG_HAS_INNER: u32 = 2u;
const FLAG_HAS_MASK: u32 = 4u;      // clip coverage x atlas mask cell
const FLAG_MASK_TEXTURE: u32 = 8u;  // mask sampled from `mask_tex`, not the atlas
const FLAG_TEX_SRGB: u32 = 16u;     // PAINT_TEXTURE source stores encoded pixels
const FLAG_BLEND_SRC: u32 = 32u;    // the composite blends in the source's space
const FLAG_UNION: u32 = 64u;        // PAINT_BACKDROP member reads the union field

// A rounded box centred at the origin. `radii` are the corner radii along x
// in the order top-left, top-right, bottom-right, bottom-left; the radius
// along y is `radius * aspect`. `exponent` is the Lamé exponent of the corner
// curve (2 = circular / elliptical).
struct Shape {
    half: vec2<f32>,
    aspect: f32,
    exponent: f32,
    radii: vec4<f32>,
}

struct Instance {
    // local -> device, kurbo coefficient order [a, b, c, d, e, f]:
    // x' = a x + c y + e ; y' = b x + d y + f.
    affine: array<vec4<f32>, 2>,
    // Quad rectangle (x0, y0, x1, y1). Local space, except KIND_GLYPH and
    // KIND_SPAN where it is the device-space atlas cell rectangle.
    bounds: vec4<f32>,
    shape: Shape,
    inner: Shape,
    // device -> clip-local affine, same coefficient order.
    clip_inv: array<vec4<f32>, 2>,
    // The clip shape; for a masked clip (always a sharp rect) `aspect` and
    // `exponent` — unread by its SDF — carry the mask cell size.
    clip: Shape,
    // Straight-alpha working-space colour (solid paint, glyph, shadow).
    color: vec4<f32>,
    // Linear: start.xy, end.xy. Radial: start centre.xy, end centre.xy.
    grad: vec4<f32>,
    // Radial: start radius, end radius.
    grad2: vec4<f32>,
    // Glyph/cell: atlas cell origin (x, y) in texels. zw: mask atlas origin.
    uv: vec4<f32>,
    // x: stroke half width (STROKE_DIST) or shadow sigma. y: opacity.
    // zw: mask device origin.
    params: vec4<f32>,
    // x: kind, y: paint, z: first stop index, w: stops | interp << 16 | extend << 20 | flags << 24
    meta_: vec4<u32>,
}

struct Stop {
    color: vec4<f32>, // straight alpha, in the interpolation space
    offset: f32,
    pad0: f32,
    pad1: f32,
    pad2: f32,
}

struct Globals {
    size: vec2<f32>,
    // Device-space origin of this pass's target region.
    origin: vec2<f32>,
    // The space the target's premultiplied pixels are stored in:
    // SPACE_LINEAR or SPACE_SRGB.
    space: u32,
    pad0: u32,
    attachment_origin: vec2<f32>,
}

const SPACE_LINEAR: u32 = 0u;
const SPACE_SRGB: u32 = 1u;

@group(0) @binding(0) var<uniform> globals: Globals;
alias InstanceBuffer = array<Instance>;
alias StopBuffer = array<Stop>;
@group(0) @binding(1) var<storage, read> instances: InstanceBuffer;
@group(0) @binding(2) var<storage, read> stops: StopBuffer;
@group(0) @binding(3) var atlas: texture_2d<f32>;

// A clip mask too large for the atlas, on its own R8Unorm texture. Both
// pipelines bind a clip-mask texture at this slot.
@group(1) @binding(3) var mask_tex: texture_2d<f32>;
struct VsOut {
    @builtin(position) position: vec4<f32>,
    // The local point of a local-space quad. A device-space quad
    // (`kind >= KIND_GLYPH`) has none: a fragment that paints it derives it
    // from the pixel (`device_quad_pixel`).
    @location(0) local: vec2<f32>,
    @location(1) device: vec2<f32>,
    @location(2) @interpolate(flat) instance: u32,
    @location(3) @interpolate(flat) meta_: vec4<u32>,
    @location(4) @interpolate(flat) color: vec4<f32>,
    @location(5) @interpolate(flat) params: vec4<f32>,
    // half.xy, aspect, exponent.
    @location(6) @interpolate(flat) shape_a: vec4<f32>,
    @location(7) @interpolate(flat) shape_radii: vec4<f32>,
    @location(8) @interpolate(flat) affine0: vec4<f32>,
    @location(9) @interpolate(flat) affine1: vec4<f32>,
    // bounds.xy, uv.xy (glyph/mask cell texel origin).
    @location(10) @interpolate(flat) cell: vec4<f32>,
    // A GPU-routed buffer cell's texel word address in the coverage
    // arena; zero for every other draw.
    @location(11) @interpolate(flat) cell_texel: u32,
}

// The angle of the vector (x, y) in [-pi, pi], the range of the oracle's
// and the CPU kernel's `atan2(y, x)`: a zero `y` of either sign takes the
// upper branch, so (x < 0, y = 0) is pi, and the zero vector is 0.
//
// Not `atan2`, whose result at the zero vector is unspecified: the sweep
// gradient's centre pixel drew a stray colour from it (#3234), and the
// compute stroker's round join between perpendicular tangents became a
// bevel with it (#2544). The angle comes from the normalized x instead.
fn angle_of(y: f32, x: f32) -> f32 {
    let r = length(vec2<f32>(y, x));
    if r == 0.0 {
        return 0.0;
    }
    return select(-1.0, 1.0, y >= 0.0) * acos(clamp(x / r, -1.0, 1.0));
}

fn apply(m: array<vec4<f32>, 2>, p: vec2<f32>) -> vec2<f32> {
    return vec2<f32>(
        m[0].x * p.x + m[0].z * p.y + m[1].x,
        m[0].y * p.x + m[0].w * p.y + m[1].y,
    );
}



// Buffer cells carry local pixel coordinates, keeping large word offsets
// out of interpolated f32 values; CPU atlas cells carry atlas coordinates.
fn cell_texel_origin(origin: vec2<f32>, packed: u32) -> vec2<f32> {
    return origin;
}

// Decode the cell coordinate convention shared by the raster entry points.
fn path_cell_coverage(texel: vec2<i32>, origin: vec2<f32>, texel_base: u32, interior: vec2<f32>, packed: u32) -> f32 {
    return textureLoad(atlas, texel, 0).r;
}

fn apply_inverse(m: array<vec4<f32>, 2>, p: vec2<f32>) -> vec2<f32> {
    let a = m[0].x;
    let b = m[0].y;
    let c = m[0].z;
    let d = m[0].w;
    let det = a * d - b * c;
    let inv_det = select(1.0 / det, 0.0, abs(det) < 1e-12);
    let q = p - m[1].xy;
    return vec2<f32>((d * q.x - c * q.y) * inv_det, (-b * q.x + a * q.y) * inv_det);
}

@vertex
fn vs_main(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VsOut {
    return quad_vertex(vi, ii);
}

fn quad_vertex(vi: u32, ii: u32) -> VsOut {
    return instance_vertex(vi, ii, instances[ii]);
}

fn instance_vertex(vi: u32, ii: u32, inst: Instance) -> VsOut {
    // Two triangles: 0 1 2, 2 1 3 over the corners (x0,y0) (x1,y0) (x0,y1) (x1,y1).
    let corner = array<u32, 6>(0u, 1u, 2u, 2u, 1u, 3u)[vi];
    let sx = f32(corner & 1u);
    let sy = f32(corner >> 1u);
    let p = vec2<f32>(mix(inst.bounds.x, inst.bounds.z, sx), mix(inst.bounds.y, inst.bounds.w, sy));
    var out: VsOut;
    if inst.meta_.x >= KIND_GLYPH {
        out.device = p;
        out.local = vec2<f32>(0.0);
    } else {
        out.local = p;
        out.device = apply(inst.affine, p);
    }
    let ndc = (out.device - globals.origin) / globals.size * 2.0 - 1.0;
    out.position = vec4<f32>(ndc.x, -ndc.y, 0.0, 1.0);
    out.instance = ii;
    // Hoist the constants every fragment reads into flat varyings so the
    // fragment shader only touches `instances` for kind-specific fields.
    out.meta_ = inst.meta_;
    // Region metadata belongs to the opaque vertex stage. Sampled coverage
    // uses the original atlas-cell fragment path for both cell kinds.
    out.meta_.x = select(inst.meta_.x, KIND_GLYPH, inst.meta_.x == KIND_REGION);
    out.color = inst.color;
    out.params = inst.params;
    out.shape_a = vec4<f32>(inst.shape.half, inst.shape.aspect, inst.shape.exponent);
    out.shape_radii = inst.shape.radii;
    out.affine0 = inst.affine[0];
    out.affine1 = inst.affine[1];
    out.cell = vec4<f32>(inst.bounds.xy, inst.uv.xy);
    return out;
}

// A device-space quad's fragment (`kind >= KIND_GLYPH`: glyph and path
// cells, regions, spans) shades the pixel whose centre is its position in
// the attachment grid, offset by that grid's device-space origin — every
// pass's viewport maps device space onto the grid at
// `globals.attachment_origin`. Interpolating the device or local point
// across the quad instead would round by where the quad's corners lie, so
// the same pixel would paint differently whenever emission cut a path
// into other cells. The device point and the local point (`apply_inverse`
// of it) are therefore functions of the pixel alone. Local-space quads
// keep their interpolated points: their corners are the shape's own.
fn device_quad_pixel(in: VsOut) -> VsOut {
    var out = in;
    if in.meta_.x >= KIND_GLYPH {
        out.device = in.position.xy + globals.attachment_origin;
        out.local = apply_inverse(array<vec4<f32>, 2>(in.affine0, in.affine1), out.device);
    }
    return out;
}

// Distance evaluations `lame_corner` spends on one point.
const LAME_EVALS: i32 = 6;
const QUARTER_PI: f32 = 0.7853981633974483;
const SQRT_HALF: f32 = 0.7071067811865476;

// A point on the Lamé quarter curve (x/r.x)^n + (y/r.y)^n = 1 at the
// parameter w = (y/r.y) / (x/r.x), w in [0, 1] from the x axis to the
// diagonal of the normalised curve: c = r·(1, w)·s with
// s = (1 + w^n)^(-1/n).
struct LamePoint {
    c: vec2<f32>,
    // (r.y, r.x·w^(n-1)): the outward normal, unnormalised.
    normal: vec2<f32>,
    // w^(n-2).
    wm2: f32,
    s: f32,
    // 1 + w^n.
    one: f32,
}

fn lame_point(r: vec2<f32>, n: f32, w: f32) -> LamePoint {
    // w^(n-2) is 1 at w = 0 for an ellipse (n = 2) and 0 for n > 2.
    var wm2 = 1.0;
    if n != 2.0 {
        wm2 = pow(max(w, 1e-30), n - 2.0);
    }
    let p = w * wm2;
    let one = 1.0 + w * p;
    let s = pow(one, -1.0 / n);
    return LamePoint(r * vec2<f32>(1.0, w) * s, vec2<f32>(r.y, r.x * p), wm2, s, one);
}

fn cbrt(x: f32) -> f32 {
    return sign(x) * pow(max(abs(x), 1e-30), 1.0 / 3.0);
}

// The largest real root of c3·x³ + c1·x + c0 = 0 with c3 > 0: Cardano's
// form where the cubic has one real root, the trigonometric form where it
// has three.
fn cubic_root(c3: f32, c1: f32, c0: f32) -> f32 {
    let p = c1 / c3;
    let h = 0.5 * c0 / c3;
    let disc = h * h + p * p * p / 27.0;
    if disc >= 0.0 {
        let e = sqrt(disc);
        return cbrt(e - h) + cbrt(-e - h);
    }
    let m = sqrt(-p / 3.0);
    return 2.0 * m * cos(acos(clamp(-h / (m * m * m), -1.0, 1.0)) / 3.0);
}

// Where the solve of an elliptical corner starts: its w = 0 end is a
// vertex of the ellipse. There the foot condition is
// F(w) = r.y·q.y - w·(r.x·q.x - Δ/√(1 + w²)), Δ = r.x² - r.y². Across a
// major vertex (Δ > 0) -F is convex and its Taylor cubic
// (Δ/2)w³ + (r.x·q.x - Δ)w - r.y·q.y bounds it from above, so the cubic's
// largest root lies just below the foot, with an error of order w⁵: the
// evolute cusp, where the foot is a near-triple root that Newton's method
// approaches only linearly, sits at small w. Across a minor vertex -F is
// concave with a slope bounded away from zero and the linear term is the
// start.
fn ellipse_start(q: vec2<f32>, r: vec2<f32>) -> f32 {
    let delta = r.x * r.x - r.y * r.y;
    let c1 = r.x * q.x - delta;
    if delta <= 0.0 {
        return clamp(r.y * q.y / c1, 0.0, 1.0);
    }
    return clamp(cubic_root(0.5 * delta, c1, -r.y * q.y), 0.0, 1.0);
}

// Where the solve of a continuous corner (r.x = r.y = r) starts: its w = 1
// end is the corner's diagonal, a vertex whose evolute cusp lies on the
// diagonal. The corner's support function about the diagonal normal is
// h(π/4 + ψ) = h0·(1 + K2·ψ² + K4·ψ⁴) with p = n/(n - 1) the dual
// exponent, so the stationarity of q·m - h(ψ) is, to third order,
// B - (A - h0 + ρ0)·ψ - ((h4 - A)/6)·ψ³ = 0 with A, B the components of q
// along and across the diagonal, ρ0 = h0·(1 + 2·K2) the radius of
// curvature and h4 = 24·h0·K4. Its largest root is the normal angle ψ away
// from the diagonal, and w = tan(π/4 - ψ)^(1/(n - 1)).
fn diagonal_start(q: vec2<f32>, r: f32, n: f32) -> f32 {
    let p = n / (n - 1.0);
    let c2 = 0.5 * p * (p - 1.0);
    let c4 = p * (p - 1.0) * (p - 2.0) * (p - 3.0) / 24.0;
    let k2 = c2 / p - 0.5;
    let k4 = (2.0 * c2 / 3.0 + c4) / p + 0.5 * (1.0 / p - 1.0) * c2 * c2 / p - 0.5 * c2 / p + 1.0 / 24.0;
    let h0 = r * exp2(1.0 / p - 0.5);
    let along = (q.x + q.y) * SQRT_HALF;
    let across = (q.x - q.y) * SQRT_HALF;
    let k3 = (24.0 * h0 * k4 - along) / 6.0;
    let k1 = along - h0 + h0 * (1.0 + 2.0 * k2);
    var psi = QUARTER_PI;
    if k3 > 0.0 {
        psi = cubic_root(k3, k1, -across);
    } else if k1 > 0.0 {
        psi = across / k1;
    }
    let theta = clamp(QUARTER_PI - psi, 0.0, QUARTER_PI);
    return clamp(pow(max(tan(theta), 1e-30), 1.0 / (n - 1.0)), 0.0, 1.0);
}

// Exact signed distance from `q` (corner-local, both components >= 0, in
// the units of `r`) to the Lamé quarter curve (q.x/r.x)^n + (q.y/r.y)^n = 1,
// for an elliptical corner (n = 2) or a continuous one (r.x = r.y, n > 2).
// Returns (d, unit normal in q space, radius of curvature at the foot).
//
// The foot is the root of F(w) = (q - c)·T, T the tangent. Folding the
// quarter at w = 1 puts it in [0, 1] with F(0) >= 0 >= F(1): an ellipse
// quarter runs between two vertices, and a continuous corner is symmetric
// about its diagonal, so the half that holds q's foot has monotone
// curvature and F changes sign on it once. The solve starts from a
// closed-form model of F about the half's vertex, where the evolute cusp
// makes the foot a near-triple root (`ellipse_start`, `diagonal_start`),
// then takes Newton steps clamped to the sign bracket, bisecting where F
// is not falling. The box is convex, so the tangent at every curve point
// supports it: the result, the distance to the tangent at the last
// iterate, never exceeds the box's signed distance and equals it at the
// foot.
fn lame_corner(q_in: vec2<f32>, r_in: vec2<f32>, n: f32) -> vec4<f32> {return vec4<f32>(q_in, r_in.x, n);}

// Distance and differential geometry evaluated at the same local point.
// In particular, a Lamé corner needs only one foot-point solve.
struct DistanceSample {
    distance: f32,
    gradient: vec4<f32>,
}

// Sharp-box distance and gradient, shared by general shapes and clipped glyphs.
fn rect_sample(half: vec2<f32>, p: vec2<f32>) -> DistanceSample {
    let sgn = select(vec2<f32>(-1.0), vec2<f32>(1.0), p >= vec2<f32>(0.0));
    let a = abs(p) - half;
    let d = length(max(a, vec2<f32>(0.0))) + min(max(a.x, a.y), 0.0);
    var g: vec4<f32>;
    if a.x > 0.0 && a.y > 0.0 {
        g = vec4<f32>(a / length(a), 0.0, 1.0);
    } else {
        g = vec4<f32>(select(vec2<f32>(0.0, 1.0), vec2<f32>(1.0, 0.0), a.x > a.y), 0.0, 0.0);
    }
    return DistanceSample(d, vec4<f32>(sgn * g.xy, g.zw));
}

fn sdf_sample(s: Shape, p: vec2<f32>, specialize_quadratic: bool) -> DistanceSample {
    let sgn = select(vec2<f32>(-1.0), vec2<f32>(1.0), p >= vec2<f32>(0.0));
    let right = p.x > 0.0;
    let bottom = p.y > 0.0;
    let r = select(
        select(s.radii.x, s.radii.w, bottom),
        select(s.radii.y, s.radii.z, bottom),
        right,
    );
    let rx = max(r, 0.0);
    let ry = rx * s.aspect;
    let a = abs(p) - s.half;
    if rx <= 0.0 || ry <= 0.0 {
        return rect_sample(s.half, p);
    }
    let q = a + vec2<f32>(rx, ry);
    if abs(s.exponent - 2.0) < 1e-4 && abs(s.aspect - 1.0) < 1e-4 {
        if q.x > 0.0 && q.y > 0.0 {
            let u = q / vec2<f32>(rx, ry);
            let len = length(u);
            let grad = length(u / vec2<f32>(rx, ry)) / max(len, 1e-6);
            let d = (len - 1.0) / max(grad, 1e-6);
            let v = q / vec2<f32>(rx * rx, ry * ry);
            let normal = v / max(length(v), 1e-12);
            return DistanceSample(d, vec4<f32>(sgn * normal, rx, 0.0));
        }
    } else if q.x >= 0.0 && q.y >= 0.0 {
        // A Lamé corner owns the lines through its centre too: on an
        // ellipse's major axis, a point deeper than the vertex's radius
        // of curvature is nearest to the curve on either side of the
        // axis, not to the vertex the straight-edge distance measures.
        // Coverage replay knows the common ellipse exponent exactly. Give
        // compilation a constant argument without changing the solve.
        var l: vec4<f32>;
        if specialize_quadratic && s.exponent == 2.0 {
            l = lame_corner(q, vec2<f32>(rx, ry), 2.0);
        } else {
            l = lame_corner(q, vec2<f32>(rx, ry), s.exponent);
        }
        return DistanceSample(l.x, vec4<f32>(sgn * l.yz, l.w, 0.0));
    }
    let g = select(vec2<f32>(0.0, 1.0), vec2<f32>(1.0, 0.0), a.x > a.y);
    return DistanceSample(max(a.x, a.y), vec4<f32>(sgn * g, 0.0, 0.0));
}

// The signed distance and unit outward normal at device point `pixel`
// of the clip shape `s` inverse-mapped by `ci` — the member-clip math
// `paint_backdrop` applies to the member's own clip and the union fold
// applies to every member's record.
fn device_sdf(ci: array<vec4<f32>, 2>, s: Shape, pixel: vec2<f32>) -> vec4<f32> {
    let pc = apply(ci, pixel);
    let sample = sdf_sample(s, pc, false);
    let g = sample.gradient;
    let dg = vec2<f32>(ci[0].x * g.x + ci[0].y * g.y, ci[0].z * g.x + ci[0].w * g.y);
    let len = max(length(dg), 1e-6);
    return vec4<f32>(sample.distance / len, dg / len, 0.0);
}

// Device-space gradient of a signed distance, for the local -> device
// affine `m` (J^-T g), before its length is scaled into per-pixel change.
fn device_grad_vec(m: array<vec4<f32>, 2>, g: vec2<f32>) -> vec2<f32> {
    let a = m[0].x;
    let b = m[0].y;
    let c = m[0].z;
    let d = m[0].w;
    return vec2<f32>(d * g.x - b * g.y, -c * g.x + a * g.y);
}

// Per-device-pixel scale for a gradient returned by `device_grad_vec`:
// |det^-1| of the affine's linear part.
fn device_grad_scale(m: array<vec4<f32>, 2>) -> f32 {
    let a = m[0].x;
    let b = m[0].y;
    let c = m[0].z;
    let d = m[0].w;
    let det = a * d - b * c;
    return abs(select(1.0 / det, 0.0, abs(det) < 1e-12));
}

// Area coverage of the axis-aligned half-plane `d <= 0` where `d`
// changes by `g` per device pixel.
fn coverage(d: f32, g: f32) -> f32 {
    return clamp(0.5 - d / g, 0.0, 1.0);
}

// Area of the unit pixel inside the half-plane `d <= 0`, with `v` the
// device-space gradient of `d` scaled by `scale` (g = |v|·scale per pixel)
// and `radius` the boundary's local radius of curvature in the same local
// units as `d` (0.0 = straight edge). Exact for straight edges at any
// angle, second-order in curvature for circular arcs; `ramp` forces the
// axis-aligned linear ramp where the distance is not a half-plane.
fn coverage_dir(d: f32, v: vec2<f32>, scale: f32, ramp: bool, radius: f32) -> f32 {
    let len = length(v);
    let g = max(len * scale, 1e-6);
    let ax = abs(v.x);
    let ay = abs(v.y);
    let b = min(ax, ay);
    if ramp {
        return coverage(d, g);
    }
    if b <= 1e-6 * len {
        let area = coverage(d, g);
        if radius > 0.0 && area > 0.0 && area < 1.0 {
            return clamp(area - (g / radius) / 24.0, 0.0, 1.0);
        }
        return area;
    }
    let a = max(ax, ay) / len;
    let bn = b / len;
    let t = -d / g;
    let h = 0.5 * (a + bn);
    let k = 0.5 * (a - bn);
    if t >= h {
        return 1.0;
    }
    if t <= -h {
        return 0.0;
    }
    if abs(t) <= k {
        let mid = 0.5 + t / a;
        if radius > 0.0 {
            let w = 1.0 / a;
            return clamp(mid - (g / radius) * w * w * w / 24.0, 0.0, 1.0);
        }
        return mid;
    }
    let e = h - abs(t);
    let tail = e * e / (2.0 * a * bn);
    let area = select(tail, 1.0 - tail, t > 0.0);
    if radius > 0.0 {
        let w = e / (a * bn);
        return clamp(area - (g / radius) * w * w * w / 24.0, 0.0, 1.0);
    }
    return area;
}

// Exact area of the unit device pixel (the square of side 1 centred on
// the fragment) inside the two half-planes `a.x + scale·dot(v1, u) <= 0`
// and `a.y + scale·dot(v2, u) <= 0`, `u` the device offset from the pixel
// centre. Sutherland–Hodgman: clip the 4-vertex square against line 1,
// then line 2, and take the shoelace area. Where a sharp corner (the two
// folded edges meeting at a point) lies inside the pixel, neither
// half-plane's linear ramp nor the exterior Euclidean ramp is the truth:
// the truth is the area inside both.
struct PolygonArea {
    first: vec2<f32>,
    previous: vec2<f32>,
    area: f32,
    count: u32,
}

fn append_area(state: PolygonArea, p: vec2<f32>) -> PolygonArea {
    var next = state;
    if state.count == 0u {
        next.first = p;
    } else {
        next.area = state.area + state.previous.x * p.y - p.x * state.previous.y;
    }
    next.previous = p;
    next.count = state.count + 1u;
    return next;
}

fn corner_coverage(a: vec2<f32>, v1: vec2<f32>, v2: vec2<f32>, scale: f32) -> f32 {
    let square = array<vec2<f32>, 4>(
        vec2<f32>(-0.5, -0.5),
        vec2<f32>(0.5, -0.5),
        vec2<f32>(0.5, 0.5),
        vec2<f32>(-0.5, 0.5),
    );
    // One half-plane adds at most one vertex to a convex square.
    var clipped: array<vec2<f32>, 5>;
    var n = 0u;
    var previous = square[3];
    var previous_distance = a.x + scale * dot(v1, previous);
    for (var i = 0u; i < 4u; i = i + 1u) {
        let p = square[i];
        let distance = a.x + scale * dot(v1, p);
        if (distance <= 0.0) != (previous_distance <= 0.0) {
            let t = previous_distance / (previous_distance - distance);
            clipped[n] = previous + t * (p - previous);
            n = n + 1u;
        }
        if distance <= 0.0 {
            clipped[n] = p;
            n = n + 1u;
        }
        previous = p;
        previous_distance = distance;
    }
    // Stream the second clip straight into the shoelace sum. This visits
    // the same vertices in the same order without a second polygon array.
    var area = PolygonArea(vec2<f32>(0.0), vec2<f32>(0.0), 0.0, 0u);
    previous = clipped[n - 1u];
    previous_distance = a.y + scale * dot(v2, previous);
    for (var i = 0u; i < n; i = i + 1u) {
        let p = clipped[i];
        let distance = a.y + scale * dot(v2, p);
        if (distance <= 0.0) != (previous_distance <= 0.0) {
            let t = previous_distance / (previous_distance - distance);
            area = append_area(area, previous + t * (p - previous));
        }
        if distance <= 0.0 {
            area = append_area(area, p);
        }
        previous = p;
        previous_distance = distance;
    }
    let sum = area.area + area.previous.x * area.first.y - area.first.x * area.previous.y;
    return clamp(abs(sum) * 0.5, 0.0, 1.0);
}

// Exact area of the unit device pixel inside the half-planes
// `p[i].x + dot(p[i].yz, u) <= 0`, `u` the device offset from the pixel
// centre: each `x` the signed outside-positive distance at the centre in
// its own local units, `yz` the distance's device-space gradient in local
// units per device pixel. Sutherland–Hodgman clips the pixel square by
// every plane in turn, so where a draw edge and a clip edge coincide the
// two planes describe the same boundary and the joint coverage is the
// single edge's — not the product of two half-covered ramps that
// multiplying the shapes' separate coverages produces (#2933). Each clip
// adds at most one vertex to the convex square: six planes need ten.
alias JointPlanes = array<vec3<f32>, 6>;

fn planes_coverage(planes: JointPlanes, count: u32) -> f32 {
    var poly: array<vec2<f32>, 10>;
    poly[0] = vec2<f32>(-0.5, -0.5);
    poly[1] = vec2<f32>(0.5, -0.5);
    poly[2] = vec2<f32>(0.5, 0.5);
    poly[3] = vec2<f32>(-0.5, 0.5);
    var n = 4u;
    for (var k = 0u; k < count; k = k + 1u) {
        let pl = planes[k];
        var clipped: array<vec2<f32>, 10>;
        var m = 0u;
        var previous = poly[n - 1u];
        var previous_distance = pl.x + dot(pl.yz, previous);
        for (var i = 0u; i < n; i = i + 1u) {
            let p = poly[i];
            let distance = pl.x + dot(pl.yz, p);
            if (distance <= 0.0) != (previous_distance <= 0.0) {
                let t = clamp(previous_distance / (previous_distance - distance), 0.0, 1.0);
                clipped[m] = previous + t * (p - previous);
                m = m + 1u;
            }
            if distance <= 0.0 {
                clipped[m] = p;
                m = m + 1u;
            }
            previous = p;
            previous_distance = distance;
        }
        if m < 3u {
            return 0.0;
        }
        for (var i = 0u; i < m; i = i + 1u) {
            poly[i] = clipped[i];
        }
        n = m;
    }
    var twice = 0.0;
    var previous = poly[n - 1u];
    for (var i = 0u; i < n; i = i + 1u) {
        let p = poly[i];
        twice = twice + previous.x * p.y - previous.y * p.x;
        previous = p;
    }
    return clamp(abs(twice) * 0.5, 0.0, 1.0);
}

// A shape's boundary at the pixel as up to two half-planes in the
// `planes_coverage` form: both faces at a sharp-corner pixel, the SDF's
// tangent plane everywhere else. The gradient is J^-T times the local
// one — `device_grad_vec(m, g) / det`, signed so a mirroring keeps the
// outward side — which `coverage_dir`'s magnitude-only use never sees.
struct ShapePlanes {
    n: u32,
    p: array<vec3<f32>, 2>,
}

struct ShapeEval {
    cov: f32,
    planes: ShapePlanes,
}

fn shape_eval(s: Shape, p: vec2<f32>, m: array<vec4<f32>, 2>, specialize_quadratic: bool) -> ShapeEval {
    var out: ShapeEval;
    let sample = sdf_sample(s, p, specialize_quadratic);
    let g = sample.gradient;
    // A sharp corner inside this pixel: the exact area inside both
    // half-planes. `a`, `sgn`, and the quadrant radius mirror `sdf_sample`;
    // the strict `<` keeps a corner exactly on a pixel boundary on the
    // old path.
    let sgn = select(vec2<f32>(-1.0), vec2<f32>(1.0), p >= vec2<f32>(0.0));
    let right = p.x > 0.0;
    let bottom = p.y > 0.0;
    let r = select(
        select(s.radii.x, s.radii.w, bottom),
        select(s.radii.y, s.radii.z, bottom),
        right,
    );
    let rx = max(r, 0.0);
    let ry = rx * s.aspect;
    let a = abs(p) - s.half;
    let det = m[0].x * m[0].w - m[0].y * m[0].z;
    if rx <= 0.0 || ry <= 0.0 {
        let scale = device_grad_scale(m);
        let v1 = device_grad_vec(m, vec2<f32>(sgn.x, 0.0));
        let v2 = device_grad_vec(m, vec2<f32>(0.0, sgn.y));
        let h1 = 0.5 * scale * (abs(v1.x) + abs(v1.y));
        let h2 = 0.5 * scale * (abs(v2.x) + abs(v2.y));
        if abs(a.x) < h1 && abs(a.y) < h2 {
            out.cov = corner_coverage(a, v1, v2, scale);
            out.planes.n = 2u;
            out.planes.p[0] = vec3<f32>(a.x, v1 / det);
            out.planes.p[1] = vec3<f32>(a.y, v2 / det);
            return out;
        }
    }
    out.cov = coverage_dir(
        sample.distance,
        device_grad_vec(m, g.xy),
        device_grad_scale(m),
        g.w > 0.0,
        g.z,
    );
    out.planes.n = 1u;
    out.planes.p[0] = vec3<f32>(sample.distance, device_grad_vec(m, g.xy) / det);
    return out;
}

// Coverage of the shape `s` at local point `p`, `m` mapping local to device.
fn shape_coverage(s: Shape, p: vec2<f32>, m: array<vec4<f32>, 2>, specialize_quadratic: bool) -> f32 {
    return shape_eval(s, p, m, specialize_quadratic).cov;
}

// The clip's boundary half-planes at the fragment, in the
// `planes_coverage` form: `clip_inv` is device → clip-local, so J^-T is
// its own transpose — the same mapping `clip_mask_coverage` applies to
// the SDF gradient.
fn clip_planes(in: VsOut) -> ShapePlanes {
    let i = in.instance;
    let s = instances[i].clip;
    let ci = instances[i].clip_inv;
    let pc = apply(ci, in.device);
    let sample = sdf_sample(s, pc, false);
    let right = pc.x > 0.0;
    let bottom = pc.y > 0.0;
    let r = select(
        select(s.radii.x, s.radii.w, bottom),
        select(s.radii.y, s.radii.z, bottom),
        right,
    );
    let rx = max(r, 0.0);
    let ry = rx * s.aspect;
    return clip_sample_planes(in, pc, sample, rx <= 0.0 || ry <= 0.0);
}

fn clip_sample_planes(in: VsOut, pc: vec2<f32>, sample: DistanceSample, sharp: bool) -> ShapePlanes {
    var out: ShapePlanes;
    let ci = instances[in.instance].clip_inv;
    let s = instances[in.instance].clip;
    let g = sample.gradient;
    let sgn = select(vec2<f32>(-1.0), vec2<f32>(1.0), pc >= vec2<f32>(0.0));
    let a = abs(pc) - s.half;
    if sharp {
        let v1 = vec2<f32>(ci[0].x * sgn.x, ci[0].z * sgn.x);
        let v2 = vec2<f32>(ci[0].y * sgn.y, ci[0].w * sgn.y);
        let h1 = 0.5 * (abs(v1.x) + abs(v1.y));
        let h2 = 0.5 * (abs(v2.x) + abs(v2.y));
        if abs(a.x) < h1 && abs(a.y) < h2 {
            out.n = 2u;
            out.p[0] = vec3<f32>(a.x, v1);
            out.p[1] = vec3<f32>(a.y, v2);
            return out;
        }
    }
    out.n = 1u;
    out.p[0] = vec3<f32>(
        sample.distance,
        vec2<f32>(ci[0].x * g.x + ci[0].y * g.y, ci[0].z * g.x + ci[0].w * g.y),
    );
    return out;
}


// The clip's atlas-or-texture mask texel at the fragment, or 1 where the
// clip carries no mask. The mask stays a coverage product: a raster cell
// has no signed-distance boundary a half-plane could intersect.
fn mask_coverage(in: VsOut) -> f32 {
    let i = in.instance;
    let flags = (in.meta_.w >> 24u) & 0xffu;
    if (flags & FLAG_HAS_MASK) == 0u {
        return 1.0;
    }
    // Mask texel for this device pixel; texels outside the cell
    // contribute zero coverage.
    let mp = floor(in.device) - in.params.zw;
    let msize = vec2<f32>(instances[i].clip.aspect, instances[i].clip.exponent);
    let inside = all(mp >= vec2<f32>(0.0)) && all(mp < msize);
    var m: f32;
    if (flags & FLAG_MASK_TEXTURE) != 0u {
        m = textureLoad(mask_tex, vec2<i32>(mp), 0).r;
    } else {
        m = textureLoad(atlas, vec2<i32>(mp) + vec2<i32>(instances[i].uv.zw), 0).r;
    }
    return select(0.0, m, inside);
}

// Coverage of the instance's clip shape and mask at `in.device`: the
// geometric clip SDF times the atlas-or-texture mask texel, matching
// fs_full's own evaluation verbatim.
fn clip_sample_coverage(in: VsOut, sample: DistanceSample) -> f32 {
    let g = sample.gradient;
    let ci = instances[in.instance].clip_inv;
    let dg = vec2<f32>(ci[0].x * g.x + ci[0].y * g.y, ci[0].z * g.x + ci[0].w * g.y);
    return coverage_dir(sample.distance, dg, 1.0, g.w > 0.0, g.z);
}

fn clip_mask_coverage(in: VsOut) -> f32 {
    let i = in.instance;
    let flags = (in.meta_.w >> 24u) & 0xffu;
    var cov = 1.0;
    if (flags & FLAG_HAS_CLIP) != 0u {
        let pc = apply(instances[i].clip_inv, in.device);
        cov = clip_sample_coverage(in, sdf_sample(instances[i].clip, pc, false));
    }
    return cov * mask_coverage(in);
}

// One premultiplied pixel moved between spaces: the space fragment's
// `space_to_srgb` / `space_from_srgb` (filtrate-core's `space::WGSL`,
// which precedes this file in every build), the conversion the CPU
// backend and the filter stages run too. Alpha carries through; a pixel
// with zero alpha becomes transparent black.
fn move_space(px: vec4<f32>, src: u32, dst: u32) -> vec4<f32> {
    if (src == dst) {
        return px;
    }
    if (dst == SPACE_SRGB) {
        return space_to_srgb(px);
    }
    return space_from_srgb(px);
}

// Cherenkov GPU slice: instanced coverage geometry for every primitive family.
//
// The painter path uses quads. Eligible solid passes first write opaque
// interiors (rectangles or inscribed octagons) with depth, then replay the
// original quads in painter order with depth tests and source-over blending.
// The vertex shader places the geometry; the fragment shader
// computes analytic coverage (an SDF, a Gaussian-blurred rounded box, or an
// atlas texel), multiplies by the instance's clip coverage and opacity, and
// evaluates the paint at the pixel centre in the instance's local space. The
// output is premultiplied linear Display P3 into an rgba16float target with
// fixed-function src-over blending.
//
// `shared.wgsl` precedes this file in every build: the consts, instance
// layout, vertex stage and coverage machinery live there.

// The Rust side prepends `const VARIANT: u32 = <n>u;` when building each
// module; the file stays compilable standalone.
const VARIANT_SIMPLE: u32 = 0u;
const VARIANT_SHADOW: u32 = 1u;
const VARIANT_FULL: u32 = 2u;
const VARIANT_UNION: u32 = 3u;
const VARIANT_LONG_GRADIENT: u32 = 4u;
// Every span but the union's: GPU-routed path draws (#2543).
const VARIANT_CELL: u32 = 5u;
const VARIANT_IMAGE: u32 = 6u;
const VARIANT_GLYPH: u32 = 7u;
const VARIANT_COMPOSITE: u32 = 8u;

@group(1) @binding(0) var source: texture_2d<f32>;
// The blend backdrop: a copy of the target's region, sampled like `source`.
@group(1) @binding(1) var backdrop: texture_2d<f32>;
@group(1) @binding(2) var image_tex: texture_2d<f32>;


// Abramowitz & Stegun 7.1.26, |error| < 1.5e-7.
fn erf(x: f32) -> f32 {
    let s = sign(x);
    let a = abs(x);
    let t = 1.0 / (1.0 + 0.3275911 * a);
    let y = 1.0 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * exp(-a * a);
    return s * y;
}

fn gaussian(x: f32, sigma: f32) -> f32 {
    return exp(-(x * x) / (2.0 * sigma * sigma)) / (2.5066282746 * sigma);
}

// Horizontal inset of a circular corner of radius `r` at distance `dy` past
// the start of the corner (dy <= 0 means the straight part of the edge).
fn corner_inset(r: f32, dy: f32) -> f32 {
    if dy <= 0.0 || r <= 0.0 {
        return 0.0;
    }
    let dd = min(dy, r);
    return r - sqrt(max(r * r - dd * dd, 0.0));
}

// One corner-band row of the shadow integrand: the analytic x integral of
// row `y` (sides inset by the corners of radii `rl`, `rr`) times the
// Gaussian weight of its distance to `p.y`.
fn corner_row(s: Shape, p: vec2<f32>, sigma: f32, k: f32, rl: f32, rr: f32, y: f32) -> f32 {
    let ay = abs(y);
    let xl = -s.half.x + corner_inset(rl, ay - (s.half.y - rl));
    let xr = s.half.x - corner_inset(rr, ay - (s.half.y - rr));
    if xr <= xl {
        return 0.0;
    }
    let row = 0.5 * (erf((xr - p.x) * k) - erf((xl - p.x) * k));
    return row * gaussian(y - p.y, sigma);
}

// The symmetric pair of Gauss–Legendre nodes `mid ± hw * x` with weight `w`.
fn corner_pair(
    s: Shape, p: vec2<f32>, sigma: f32, k: f32, rl: f32, rr: f32,
    mid: f32, hw: f32, x: f32, w: f32,
) -> f32 {
    return (corner_row(s, p, sigma, k, rl, rr, mid - hw * x)
        + corner_row(s, p, sigma, k, rl, rr, mid + hw * x)) * w * hw;
}

// Indicator of the rounded box `s` (circular corners), convolved with an
// isotropic Gaussian of standard deviation `sigma`, evaluated at `p`. The x
// integral of each row is analytic (erf); the y integral over the corner
// bands within ±3σ is an 8-point Gauss–Legendre rule.
fn shadow(s: Shape, p: vec2<f32>, sigma: f32) -> f32 {
    let k = 1.0 / (sigma * 1.4142135624);
    // Rows within ±3σ of p that intersect the box.
    let lo = max(p.y - 3.0 * sigma, -s.half.y);
    let hi = min(p.y + 3.0 * sigma, s.half.y);
    if hi <= lo {
        return 0.0;
    }
    let rmax = max(max(max(s.radii.x, s.radii.y), max(s.radii.z, s.radii.w)), 0.0);
    // Rows whose corner insets are beyond 4σ of p integrate like straight rows.
    let straight = abs(p.x) <= s.half.x - rmax - 4.0 * sigma;
    // Rows |y| < band have straight sides: the integral is separable.
    let band = select(max(s.half.y - rmax, 0.0), s.half.y, straight);
    var acc = 0.0;
    let ya = max(lo, -band);
    let yb = min(hi, band);
    if yb > ya {
        let row = 0.5 * (erf((s.half.x - p.x) * k) - erf((-s.half.x - p.x) * k));
        acc += row * 0.5 * (erf((yb - p.y) * k) - erf((ya - p.y) * k));
    }
    // Corner bands: Gauss–Legendre over the rows still inside ±3σ.
    for (var side = 0; side < 2; side++) {
        let top = side == 0;
        let a = max(select(band, lo, top), lo);
        let b = min(select(hi, -band, top), hi);
        if b <= a {
            continue;
        }
        let rl = select(s.radii.w, s.radii.x, top);
        let rr = select(s.radii.z, s.radii.y, top);
        let mid = 0.5 * (a + b);
        let hw = 0.5 * (b - a);
        acc += corner_pair(s, p, sigma, k, rl, rr, mid, hw, 0.1834346425, 0.3626837834);
        acc += corner_pair(s, p, sigma, k, rl, rr, mid, hw, 0.5255324099, 0.3137066459);
        acc += corner_pair(s, p, sigma, k, rl, rr, mid, hw, 0.7966664774, 0.2223810345);
        acc += corner_pair(s, p, sigma, k, rl, rr, mid, hw, 0.9602898565, 0.1012285363);
    }
    return clamp(acc, 0.0, 1.0);
}

// Returns false when EXTEND_NONE leaves t outside [0,1] — the caller
// returns transparent. NaN fails the range test and is also rejected.
fn extend_ok(t: f32, mode: u32) -> bool {
    return mode != EXTEND_NONE || (t >= 0.0 && t <= 1.0);
}

fn extend_t(t: f32, mode: u32) -> f32 {
    switch mode {
        case EXTEND_REPEAT: {
            return t - floor(t);
        }
        case EXTEND_REFLECT: {
            let m = t - 2.0 * floor(t * 0.5);
            return 1.0 - abs(m - 1.0);
        }
        default: {
            return clamp(t, 0.0, 1.0);
        }
    }
}

// Premultiplied working-space colour of the gradient at parameter `t`.
fn eval_stops(first: u32, count: u32, interp: u32, t: f32) -> vec4<f32> {
    var c: vec4<f32>;
    if count == 0u {
        return vec4<f32>(0.0);
    }
    if t <= stops[first].offset || count == 1u {
        c = stops[first].color;
    } else if t >= stops[first + count - 1u].offset {
        c = stops[first + count - 1u].color;
    } else {
        var i = first;
        loop {
            if i + 1u >= first + count - 1u || t < stops[i + 1u].offset {
                break;
            }
            i += 1u;
        }
        let s0 = stops[i];
        let s1 = stops[i + 1u];
        let span = s1.offset - s0.offset;
        let f = select((t - s0.offset) / span, 0.0, span <= 0.0);
        c = mix(s0.color, s1.color, f);
    }
    var rgb = c.rgb;
    if interp == INTERP_SRGB {
        rgb = SPACE_SRGB_TO_P3 * space_srgb_decode(rgb);
    }
    return vec4<f32>(rgb * c.a, c.a);
}

fn linear_t(i: u32, p: vec2<f32>) -> f32 {
    let d = instances[i].grad.zw - instances[i].grad.xy;
    let dd = dot(d, d);
    if dd <= 0.0 {
        return 0.0;
    }
    return dot(p - instances[i].grad.xy, d) / dd;
}

// Two-point conical gradient parameter, a literal port of the oracle's
// radial_t: the largest root of |p - (c0 + t·dc)| = r0 + t·dr whose radius
// r0 + t·dr is non-negative; `valid` is false where there is none.
// Identical circles (grad2.z set by lowering) take t = -∞ inside r0 and
// +∞ outside. WGSL rejects non-finite constants, so `side` carries that
// sign (-1 or +1, 0 for a finite `value`); lowering rejects identical
// circles under repeat and reflect.
struct RadialParameter {
    value: f32,
    valid: bool,
    side: f32,
}
fn radial_t(i: u32, p: vec2<f32>) -> RadialParameter {
    let c0 = instances[i].grad.xy;
    let c1 = instances[i].grad.zw;
    let r0 = instances[i].grad2.x;
    let r1 = instances[i].grad2.y;
    let pd = p - c0;
    if instances[i].grad2.z != 0.0 {
        return RadialParameter(0.0, true, select(1.0, -1.0, length(pd) <= r0));
    }
    let dc = c1 - c0;
    let dr = r1 - r0;
    let a = dot(dc, dc) - dr * dr;
    // b = -2·((p - c0)·dc + r0·dr)
    let b = -2.0 * (dot(pd, dc) + r0 * dr);
    let c = dot(pd, pd) - r0 * r0;
    if abs(a) < 1e-12 {
        if abs(b) < 1e-12 {
            return RadialParameter(0.0, false, 0.0);
        }
        let t = -c / b;
        return RadialParameter(t, r0 + t * dr >= 0.0, 0.0);
    }
    let disc = b * b - 4.0 * a * c;
    if disc < 0.0 {
        return RadialParameter(0.0, false, 0.0);
    }
    let sq = sqrt(disc);
    // When `a` is negative the larger root has the smaller numerator, so
    // compare the roots themselves.
    let q0 = (-b + sq) / (2.0 * a);
    let q1 = (-b - sq) / (2.0 * a);
    let hi = max(q0, q1);
    if r0 + hi * dr >= 0.0 {
        return RadialParameter(hi, true, 0.0);
    }
    let lo = min(q0, q1);
    return RadialParameter(lo, r0 + lo * dr >= 0.0, 0.0);
}

// Sweep (conic) parameter: the wrapped angle of p - center mapped into
// [start_angle, end_angle). A literal port of the oracle's sweep_t.
fn sweep_t(i: u32, p: vec2<f32>) -> f32 {
    let start = instances[i].grad2.x;
    var end = instances[i].grad2.y;
    let tau = 6.283185307179586;
    while end <= start {
        end += tau;
    }
    let span = end - start;
    let c = instances[i].grad.xy;
    var theta = angle_of(p.y - c.y, p.x - c.x);
    while theta < start {
        theta += tau;
    }
    while theta >= start + tau {
        theta -= tau;
    }
    return (theta - start) / span;
}

// A loaded image texel in the working representation. Only the image
// variant (and union, which carries everything) converts source texels:
// the `// image-source` spans are dropped from every other variant, whose
// image paints all sample working texels (flags 0).
fn image_working_texel(encoded: vec4<f32>, flags: u32) -> vec4<f32> {
    return encoded;
}


// Samples `tex` like the oracle's sample_image: texel centres at n + 0.5,
// coordinate already in image-pixel space after the per-axis extend.
fn sample_image_tex(tex: texture_2d<f32>, u: f32, v: f32, w: f32, h: f32, bilinear: bool, flags: u32) -> vec4<f32> {
    let dims = vec2<f32>(w, h);
    if bilinear {
        // Clamp the sample coordinate into texel-centre space before the
        // fraction: taps outside the border texels collapse onto the edge.
        let f = clamp(vec2<f32>(u, v) - 0.5, vec2<f32>(0.0), dims - 1.0);
        let lo = vec2<i32>(floor(f));
        let hi = min(lo + 1, vec2<i32>(dims) - 1);
        let t = f - floor(f);
        let c00 = image_working_texel(textureLoad(tex, vec2<i32>(lo.x, lo.y), 0), flags);
        let c10 = image_working_texel(textureLoad(tex, vec2<i32>(hi.x, lo.y), 0), flags);
        let c01 = image_working_texel(textureLoad(tex, vec2<i32>(lo.x, hi.y), 0), flags);
        let c11 = image_working_texel(textureLoad(tex, vec2<i32>(hi.x, hi.y), 0), flags);
        return mix(mix(c00, c10, t.x), mix(c01, c11, t.x), t.y);
    }
    let xy = clamp(round(vec2<f32>(u, v) - 0.5), vec2<f32>(0.0), dims - 1.0);
    return image_working_texel(textureLoad(tex, vec2<i32>(xy), 0), flags);
}

// Image paint: `grad`/`grad2` carry the local→image affine [a b c d e f]
// and the image size [w, h]; meta_.w packs extend_x | extend_y<<4 |
// sampling<<8 and source conversion flags in bits 12–16. The extends run in image-pixel space, like the oracle's
// eval_image_paint.
fn paint_image(i: u32, local: vec2<f32>) -> vec4<f32> {
    let g = instances[i].grad;
    let g2 = instances[i].grad2;
    let q = vec2<f32>(
        g.x * local.x + g.z * local.y + g2.x,
        g.y * local.x + g.w * local.y + g2.y,
    );
    let meta_w = instances[i].meta_.w;
    let ex = meta_w & 0xfu;
    let ey = (meta_w >> 4u) & 0xfu;
    let tu = q.x / g2.z;
    let tv = q.y / g2.w;
    if !extend_ok(tu, ex) || !extend_ok(tv, ey) {
        return vec4<f32>(0.0);
    }
    let u = extend_t(tu, ex) * g2.z;
    let v = extend_t(tv, ey) * g2.w;
    return sample_image_tex(image_tex, u, v, g2.z, g2.w, ((meta_w >> 8u) & 1u) != 0u, meta_w);
}

// Bilinear inverse in f32, solving for v. The f64 oracle solves for u.
fn mesh_cross(a: vec2<f32>, b: vec2<f32>) -> f32 {
    return a.x * b.y - a.y * b.x;
}

fn mesh_uv(point: vec2<f32>, top: vec4<f32>, bottom: vec4<f32>) -> vec3<f32> {
    let horizontal = top.zw - top.xy;
    let vertical = bottom.xy - top.xy;
    let bend = bottom.zw - bottom.xy - horizontal;
    let delta = point - top.xy;
    let qa = -mesh_cross(vertical, bend);
    let qb = mesh_cross(delta, bend) - mesh_cross(vertical, horizontal);
    let qc = mesh_cross(delta, horizontal);
    var roots = vec2<f32>(-1.0);
    if qa == 0.0 {
        if qb == 0.0 { return vec3<f32>(0.0); }
        roots = vec2<f32>(-qc / qb);
    } else {
        let discriminant = qb * qb - 4.0 * qa * qc;
        if discriminant < 0.0 { return vec3<f32>(0.0); }
        let signed_root = select(-sqrt(discriminant), sqrt(discriminant), qb >= 0.0);
        let numerator = -0.5 * (qb + signed_root);
        roots = vec2<f32>(numerator / qa);
        if numerator != 0.0 { roots.y = qc / numerator; }
    }
    var answer = vec3<f32>(0.0);
    for (var index = 0u; index < 2u; index += 1u) {
        let v = roots[index];
        if !(v >= 0.0 && v <= 1.0) { continue; }
        let direction = horizontal + v * bend;
        let remainder = delta - v * vertical;
        var u: f32;
        if abs(direction.x) >= abs(direction.y) {
            if direction.x == 0.0 { continue; }
            u = remainder.x / direction.x;
        } else {
            u = remainder.y / direction.y;
        }
        if !(u >= 0.0 && u <= 1.0) { continue; }
        if mesh_cross(direction, vertical + u * bend) == 0.0 { continue; }
        if answer.z == 0.0 || v > answer.y || (v == answer.y && u > answer.x) {
            answer = vec3<f32>(u, v, 1.0);
        }
    }
    return answer;
}

fn paint_mesh(first: u32, count: u32, point: vec2<f32>, smooth_color: bool) -> vec4<f32> {
    for (var remaining = count; remaining > 0u; remaining -= 1u) {
        let base = first + (remaining - 1u) * 6u;
        let uv = mesh_uv(point, stops[base].color, stops[base + 1u].color);
        if uv.z != 0.0 {
            var weight = uv.xy;
            if smooth_color { weight = weight * weight * (3.0 - 2.0 * weight); }
            let top = mix(stops[base + 2u].color, stops[base + 3u].color, weight.x);
            let bottom = mix(stops[base + 4u].color, stops[base + 5u].color, weight.x);
            return mix(top, bottom, weight.y);
        }
    }
    return vec4<f32>(0.0);
}

fn paint(i: u32, meta_: vec4<u32>, color: vec4<f32>, local: vec2<f32>, device: vec2<f32>) -> vec4<f32> {
    let kind = meta_.y & 0xffffu;
    var point = local;
    if (meta_.y & 0x10000u) != 0u {
        let linear = stops[meta_.z - 2u].color;
        let offset = stops[meta_.z - 1u].color.xy;
        point = vec2<f32>(linear.x * local.x + linear.z * local.y,
                          linear.y * local.x + linear.w * local.y) + offset;
    }
    // non-gradient-paint
    switch kind {
        case PAINT_SOLID: {
            return vec4<f32>(color.rgb * color.a, color.a);
        }
        case PAINT_TEXTURE: {
            // `grad.xy` carries the source region's device-space origin.
            return textureLoad(source, vec2<i32>(floor(device - instances[i].grad.xy)), 0);
        }
        case PAINT_MESH: {
            return paint_mesh(meta_.z, meta_.w & 0x00ffffffu, point, (meta_.y & 0x20000u) != 0u);
        }
        case PAINT_IMAGE: {
            return paint_image(i, point);
        }
        default: {
    // non-gradient-paint
            let meta_w = meta_.w;
            let extend = (meta_w >> 20u) & 0xfu;
            var t: f32;
            if kind == PAINT_LINEAR {
                t = linear_t(i, point);
            } else if kind == PAINT_SWEEP {
                t = sweep_t(i, point);
            } else {
                let radial = radial_t(i, point);
                if !radial.valid {
                    return vec4<f32>(0.0);
                }
                if radial.side != 0.0 {
                    // t = ±∞ clamps to an end stop under pad and is outside
                    // the range of every other mode lowering accepts.
                    if extend != EXTEND_PAD {
                        return vec4<f32>(0.0);
                    }
                    t = max(radial.side, 0.0);
                } else {
                    t = radial.value;
                }
            }
            // NaN (exponent all-ones, nonzero mantissa) → transparent.
            // `t != t` is not reliable under every driver.
            let tbits = bitcast<u32>(t);
            if (tbits & 0x7f800000u) == 0x7f800000u && (tbits & 0x007fffffu) != 0u {
                return vec4<f32>(0.0);
            }
            let interp = (meta_w >> 16u) & 0xfu;
            let count = meta_w & 0xffffu;
            if !extend_ok(t, extend) {
                return vec4<f32>(0.0);
            }
            return eval_stops(instances[i].meta_.z, count, interp, extend_t(t, extend));
    // non-gradient-paint
        }
    }
    // non-gradient-paint
}

// Per-member backdrop effects: a member composite bilinearly samples the
// bound capture and applies the effect packed in meta_.w's low bits.
// `backdrop_origin`/`backdrop_size`/`backdrop_scale`/`backdrop_levels`
// are set per instance by paint_backdrop; registered effect shaders call
// backdrop_sample and backdrop_sample_level.
var<private> backdrop_origin: vec2<f32>;
var<private> backdrop_size: vec2<f32>;
var<private> backdrop_scale: f32;
var<private> backdrop_levels: f32;

// Bilinear sample of the bound capture's level `k` at device point `q`:
// on the level-k grid `q` is `q · scale / 2^k`, the four texels around
// it minus 0.5 (texel centres) are read at mip `k`, clamped to the
// level's extent `ceil(backdrop_size / 2^k)`, values unclamped. The
// region's texel origin is aligned to `2^k`, so the level-k origin is
// `backdrop_origin / 2^k` exactly.
fn backdrop_sample_at(q: vec2<f32>, k: u32) -> vec4<f32> {
    let div = f32(1u << k);
    let size = (vec2<u32>(backdrop_size) + vec2<u32>((1u << k) - 1u)) >> vec2<u32>(k);
    let f = clamp(
        (q * backdrop_scale - backdrop_origin) / div - 0.5,
        vec2<f32>(0.0),
        vec2<f32>(size) - 1.0,
    );
    let lo = vec2<i32>(floor(f));
    let hi = min(lo + 1, vec2<i32>(size) - 1);
    let t = f - floor(f);
    let c00 = textureLoad(source, lo, i32(k));
    let c10 = textureLoad(source, vec2<i32>(hi.x, lo.y), i32(k));
    let c01 = textureLoad(source, vec2<i32>(lo.x, hi.y), i32(k));
    let c11 = textureLoad(source, hi, i32(k));
    return mix(mix(c00, c10, t.x), mix(c01, c11, t.x), t.y);
}

// Bilinear sample of the bound capture at device point `q`: on the
// capture grid `q` is `q · scale`, and the four texels around it minus
// 0.5 (texel centres) are read, clamped to the capture region, values
// unclamped.
fn backdrop_sample(q: vec2<f32>) -> vec4<f32> {
    return backdrop_sample_at(q, 0u);
}

// Trilinear sample of the capture pyramid at device point `q`: `level`
// clamps to `[0, backdrop_levels − 1]` and the read is bilinear at
// `floor(level)` and `ceil(level)`, mixed by `fract(level)`.
fn backdrop_sample_level(q: vec2<f32>, level: f32) -> vec4<f32> {
    let lc = clamp(level, 0.0, backdrop_levels - 1.0);
    let base = floor(lc);
    let k0 = u32(base);
    let lo = backdrop_sample_at(q, k0);
    let phase = lc - base;
    if phase == 0.0 { return lo; }
    let k1 = min(k0 + 1u, u32(backdrop_levels) - 1u);
    let hi = backdrop_sample_at(q, k1);
    return mix(lo, hi, phase);
}

// The effect entry's pixel input: the device-space sample point, the
// signed distance of the field the member draws against — the group's
// union field when it has one, the member's own clip distance
// otherwise — the unit outward normal of that field, the member's own
// signed distance, the member's device size, the device pixels per
// logical pixel of the member's recording, and the sample point in the
// member layer's own coordinate space (the space its clip is declared
// in).
struct BackdropPixel {
    p: vec2<f32>,
    sdf: f32,
    normal: vec2<f32>,
    own_sdf: f32,
    size: vec2<f32>,
    scale: f32,
    local: vec2<f32>,
}

// The field a member draws against, read at any device point: its signed
// distance, the unit outward normal there and the member's ownership
// weight — its share of the point under a union, 1 otherwise.
struct BackdropField {
    sdf: f32,
    normal: vec2<f32>,
    weight: f32,
}

// The instance paint_backdrop is compositing: backdrop_field reads the
// member's clip or union record from it.
var<private> backdrop_member: u32;

// The member's field at device point `q`: the group's union field — the
// same fold and ownership the composite evaluates at its own pixel —
// for a union member, the member's own clip distance otherwise. At
// `q = px.p` it is exactly `px.sdf` and `px.normal`.
fn backdrop_field(q: vec2<f32>) -> BackdropField {
    let inst = instances[backdrop_member];
    let own = device_sdf(inst.clip_inv, inst.clip, q);
    return BackdropField(own.x, own.yz, 1.0);
}

// backdrop-effect-stub
fn backdrop_effect(px: BackdropPixel, params: array<vec4<f32>, 16>) -> vec4<f32> {
    return backdrop_sample(px.p);
}
// backdrop-effect-stub

// The member composite for a PAINT_BACKDROP instance: the effect in
// meta_.w's low bits (`kind | stop count << 8`) evaluated at the device
// pixel centre `pixel`. grad.xy is the capture origin, grad.z the capture
// scale, grad.w its level count, grad2.xy its size, grad2.zw the member's
// device size, color.x the member's recording scale, the instance
// affine the member layer's local-to-device transform.
fn paint_backdrop(i: u32, pixel: vec2<f32>) -> vec4<f32> {
    let inst = instances[i];
    backdrop_member = i;
    backdrop_origin = inst.grad.xy;
    backdrop_scale = inst.grad.z;
    backdrop_levels = inst.grad.w;
    backdrop_size = inst.grad2.xy;
    let kind = inst.meta_.w & 0xffu;
    let first = inst.meta_.z;
    if kind == EFFECT_SAMPLE {
        return backdrop_sample(pixel);
    }
    if kind == EFFECT_COLOR {
        // 3x4 premultiplied matrix, filtrate ColorMatrix layout:
        // dot(row, c) per channel, alpha passes through.
        let c = backdrop_sample(pixel);
        return vec4<f32>(
            dot(stops[first].color, c),
            dot(stops[first + 1u].color, c),
            dot(stops[first + 2u].color, c),
            c.a,
        );
    }
    // Refraction and effect shaders need the member clip's SDF: signed
    // distance and unit outward normal in device space, the same
    // J^-T math the clip coverage block uses. A union member's own clip
    // lives in its union record — the instance clip then carries the
    // ancestors only — and the shared field replaces both `sdf` and
    // `normal` for every effect kind.
    var px: BackdropPixel;
    px.p = pixel;
    px.size = inst.grad2.zw;
    px.scale = inst.color.x;
    px.local = apply_inverse(inst.affine, pixel);
    {
        let own = device_sdf(inst.clip_inv, inst.clip, pixel);
        px.own_sdf = own.x;
        px.sdf = own.x;
        px.normal = own.yz;
    }
    let d = px.sdf;
    let n = px.normal;
    if kind == EFFECT_REFRACTION {
        // stops[first].color.xy = (depth, strength).
        let p0 = stops[first].color;
        let t = clamp(1.0 + d / p0.x, 0.0, 1.0);
        return backdrop_sample(pixel - n * p0.y * t * t);
    }
    if kind == EFFECT_RIM {
        // stops[first].color = (width, r, g, b); stops[first+1].color =
        // (a, gain). The rim is an additive term on the sampled colour
        // (alpha unchanged — gaining alpha would cancel under src-over).
        let p0 = stops[first].color;
        let p1 = stops[first + 1u].color;
        let t = clamp(1.0 + d / p0.x, 0.0, 1.0);
        let k = p1.x * p1.y * t * t;
        let c = backdrop_sample(pixel);
        return vec4<f32>(c.rgb + p0.yzw * k, c.a);
    }
    if kind == EFFECT_LEVEL {
        // stops[first].color = (depth, edge, interior): the pyramid
        // level ramps from `edge` at the clip's edge (t = 1) to
        // `interior` deep inside (t = 0).
        let p0 = stops[first].color;
        let t = clamp(1.0 + d / p0.x, 0.0, 1.0);
        return backdrop_sample_level(pixel, p0.z + (p0.y - p0.z) * t);
    }
    var params = array<vec4<f32>, 16>();
    let count = (inst.meta_.w >> 8u) & 0xffu;
    for (var j = 0u; j < count; j = j + 1u) {
        params[j] = stops[first + j].color;
    }
    return backdrop_effect(px, params);
}

// The tile build profile replaces these two interfaces with attachment
// inputs. Coverage, colour conversion and blend arithmetic remain shared.
fn read_composite_source(coord: vec2<i32>) -> vec4<f32> {
    return textureLoad(source, coord, 0);
}

fn read_composite_backdrop(coord: vec2<i32>) -> vec4<f32> {
    return textureLoad(backdrop, coord, 0);
}

// Solid fill/span/glyph coverage: no clip, mask, inner, or paint()
// evaluation, and no `instances` reads at all.
fn fs_simple(in: VsOut, classified: bool) -> vec4<f32> {
    let s = Shape(in.shape_a.xy, in.shape_a.z, in.shape_a.w, in.shape_radii);
    let m = array<vec4<f32>, 2>(in.affine0, in.affine1);
    var cov: f32;
    switch in.meta_.x {
        case KIND_GLYPH: {
            var texel: vec2<i32>;
            if classified {
                texel = vec2<i32>(floor(in.local));
            } else {
                texel = vec2<i32>(floor(in.device - in.cell.xy)) + vec2<i32>(cell_texel_origin(in.cell.zw, in.meta_.w));
            }
            cov = path_cell_coverage(texel, in.cell.zw, in.cell_texel, in.shape_a.xy, in.meta_.w);
        }
        case KIND_SPAN: {
            cov = 1.0;
        }
        default: {
            if classified && in.affine1.w > 0.0 {
                let r = vec2<f32>(s.half.x, s.half.x * s.aspect);
                let u = abs(in.local) / r;
                let rr = dot(u, u);
                if rr < in.affine1.z {
                    cov = 1.0;
                } else if rr > in.affine1.w {
                    cov = 0.0;
                } else {
                    cov = shape_coverage(s, in.local, m, classified);
                }
            } else {
                cov = shape_coverage(s, in.local, m, classified);
            }
        }
    }
    cov = clamp(cov, 0.0, 1.0) * in.params.y;
    return move_space(vec4<f32>(in.color.rgb * in.color.a, in.color.a) * cov, SPACE_LINEAR, globals.space);
}

// Retained path spans already describe full coverage. Their opacity is
// uniform over the primitive, so the vertex stage can select them without
// fragment discard (which would prevent early hidden-surface removal).
fn opaque_span(inst: Instance) -> bool {
    return inst.meta_.x == KIND_SPAN && inst.color.a * inst.params.y == 1.0;
}

struct OpaqueOut {
    @builtin(position) position: vec4<f32>,
    @location(0) @interpolate(flat) color: vec3<f32>,
}

// Coverage replay needs only the original local/atlas coordinate, the
// instance identity, and the conservative ellipse bounds. Pull the uniform
// primitive fields in the fragment stage instead of duplicating them in
// every vertex's rasterizer payload.
struct PartialOut {
    @builtin(position) position: vec4<f32>,
    @location(0) local: vec2<f32>,
    @location(1) @interpolate(flat) instance: u32,
    @location(2) @interpolate(flat) coverage: vec2<f32>,
}

@vertex
fn vs_opaque(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> OpaqueOut {
    var inst = instances[ii];
    var ellipse = false;
    var ellipse_half = vec2<f32>(0.0);
    var inst_index = ii;
    var corner_vi = vi;
    var tier = 0u;
    var promoted = false;
    if inst.meta_.x == KIND_REGION {
        let x = inst.bounds.x;
        inst.bounds.x = x + f32(inst.meta_.z & 0xffffu);
        inst.bounds.z = x + f32(inst.meta_.z >> 16u);
    }
    if inst.meta_.x == KIND_POLYGON {
        // An appended interior tier: grad.x bitcast holds the painter
        // index it stands for, meta_.w its polygon side count.
        inst_index = bitcast<u32>(inst.grad.x);
        tier = inst.meta_.w & 3u;
        inst.meta_.x = KIND_FILL;
    } else if inst.meta_.x == KIND_FILL {
        // meta_.w's low bits mark a fill whose interior an appended
        // polygon covers: the polygon contains the octagon's every
        // vertex, so this interior emits nothing.
        promoted = (inst.meta_.w & 3u) != 0u;
    }
    if inst.meta_.x == KIND_FILL {
        let m = inst.affine[0];
        let det = abs(m.x * m.w - m.y * m.z);
        let margin = vec2<f32>(abs(m.w) + abs(m.z), abs(m.y) + abs(m.x)) / det;
        let s = inst.shape;
        ellipse = s.exponent == 2.0 && all(s.radii == vec4<f32>(s.half.x));
        ellipse_half = s.half * max(1.0 - length(margin / s.half), 0.0);
        let radius = max(max(s.radii.x, s.radii.y), max(s.radii.z, s.radii.w));
        // The rectangle inscribed in the circular corners is inside every
        // supported Lamé corner (exponent >= 2). Inset one complete device
        // pixel on each local axis, beyond the analytic AA support.
        let half = s.half - radius * (1.0 - sqrt(0.5)) * vec2<f32>(1.0, s.aspect) - margin;
        inst.bounds = vec4<f32>(max(inst.bounds.xy, -half), min(inst.bounds.zw, half));
    }
    let corner = array<u32, 4>(0u, 1u, 2u, 5u)[min(corner_vi, 3u)];
    var out = instance_vertex(corner, inst_index, inst);
    if ellipse {
        var ndc: vec2<f32>;
        if tier == 0u {
            let d = sqrt(0.5);
            let polygon = array<vec2<f32>, 8>(
                vec2<f32>(1.0, 0.0), vec2<f32>(d, d),
                vec2<f32>(0.0, 1.0), vec2<f32>(-d, d),
                vec2<f32>(-1.0, 0.0), vec2<f32>(-d, -d),
                vec2<f32>(0.0, -1.0), vec2<f32>(d, -d),
            );
            let index = array<u32, 8>(0u, 1u, 7u, 2u, 6u, 3u, 5u, 4u)[corner_vi];
            let p = polygon[index] * max(ellipse_half, vec2<f32>(0.0));
            ndc = (apply(inst.affine, p) - globals.origin) / globals.size * 2.0 - 1.0;
        } else {
            // Zigzag order covers a regular n-gon as a strip.
            let n = 8u << tier;
            let k = select((n - vi / 2u) % n, (vi + 1u) / 2u, (vi & 1u) == 1u);
            let a = f32(k) * 6.283185307179586 / f32(n);
            let p = vec2<f32>(cos(a), sin(a)) * max(ellipse_half, vec2<f32>(0.0));
            ndc = (apply(inst.affine, p) - globals.origin) / globals.size * 2.0 - 1.0;
        }
        out.position = vec4<f32>(ndc.x, -ndc.y, 0.0, 1.0);
    }
    // Each index selects a distinct positive f32 depth starting at 0.125,
    // spaced eight ulps apart. GL's clip z runs [-1, 1]: naga remaps it as
    // z*2 - w in f32, where |z| near 0.75 quantises to 2^-24 — the index
    // spacing must exceed that quantum (here: 4 of them, landing on grid)
    // or neighbouring indices collapse and the replay's depth test fails.
    // Depths stay below 0.5 for 2^21 instances (below 1.0 for ~3.1M);
    // render/mod.rs's MAX_PASS_INSTANCES enforces the bound.
    out.position.z = bitcast<f32>(0x3e000000u + inst_index * 8u + select(0u, 4u, tier != 0u));
    if inst.color.a * inst.params.y != 1.0
        || (inst.meta_.x != KIND_SPAN && inst.meta_.x != KIND_FILL && inst.meta_.x != KIND_REGION)
        || any(inst.bounds.xy >= inst.bounds.zw)
        || promoted {
        out.position = vec4<f32>(0.0, 0.0, 0.0, 1.0);
    }
    return OpaqueOut(out.position, out.color.rgb);
}

@vertex
fn vs_partial(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> PartialOut {
    var out: VsOut;
    var inst: Instance;
    var depth_index = ii;
        out = quad_vertex(array<u32, 8>(0u, 1u, 2u, 5u, 5u, 5u, 5u, 5u)[vi], ii);
        inst = instances[ii];
    out.position.z = bitcast<f32>(0x3e000000u + depth_index * 8u);
    let s = inst.shape;
    if inst.meta_.x == KIND_FILL && s.exponent == 2.0 && all(s.radii == vec4<f32>(s.half.x)) {
        let m = inst.affine[0];
        let r = vec2<f32>(s.half.x, s.half.x * s.aspect);
        let h = 0.5 * device_grad_scale(inst.affine) * vec2<f32>(abs(m.w) + abs(m.z), abs(m.y) + abs(m.x));
        let margin = length(h) / min(r.x, r.y);
        out.affine1.z = max(1.0 - margin, 0.0) * max(1.0 - margin, 0.0);
        out.affine1.w = (1.0 + margin) * (1.0 + margin);
    }
    if opaque_span(inst) {
        out.position = vec4<f32>(0.0, 0.0, 0.0, 1.0);
    }
    let local = select(out.local, out.device - out.cell.xy + cell_texel_origin(out.cell.zw, out.meta_.w), out.meta_.x == KIND_GLYPH);
    return PartialOut(
        out.position,
        local,
        out.instance,
        out.affine1.zw,
    );
}

@fragment
fn fs_opaque(in: OpaqueOut) -> @location(0) vec4<f32> {
    return move_space(vec4<f32>(in.color, 1.0), SPACE_LINEAR, globals.space);
}

@fragment
fn fs_partial(in: PartialOut) -> @location(0) vec4<f32> {
    let inst = instances[in.instance];
    var data: VsOut;
    data.local = in.local;
    var kind = inst.meta_.x;
    data.meta_.x = select(kind, KIND_GLYPH, kind == KIND_REGION);
    data.color = inst.color;
    data.params.y = inst.params.y;
    if data.meta_.x != KIND_GLYPH && data.meta_.x != KIND_SPAN {
        data.shape_a = vec4<f32>(inst.shape.half, inst.shape.aspect, inst.shape.exponent);
        data.shape_radii = inst.shape.radii;
        data.affine0 = inst.affine[0];
    }
    data.affine1 = vec4<f32>(0.0, 0.0, in.coverage);
    return fs_simple(data, true);
}

// The shadow kernel plus the same opacity/solid-colour tail.
fn fs_shadow(in: VsOut) -> vec4<f32> {
    let s = Shape(in.shape_a.xy, in.shape_a.z, in.shape_a.w, in.shape_radii);
    let m = array<vec4<f32>, 2>(in.affine0, in.affine1);
    let sigma = in.params.x;
    var cov: f32;
    if sigma < 0.25 {
        cov = shape_coverage(s, in.local, m, false);
    } else {
        cov = shadow(s, in.local, sigma);
    }
    cov = clamp(cov, 0.0, 1.0) * in.params.y;
    return move_space(vec4<f32>(in.color.rgb * in.color.a, in.color.a) * cov, SPACE_LINEAR, globals.space);
}

fn glyph_coverage(in: VsOut) -> f32 {
    let texel = vec2<i32>(floor(in.device - in.cell.xy)) + vec2<i32>(cell_texel_origin(in.cell.zw, in.meta_.w));
    return path_cell_coverage(texel, in.cell.zw, in.cell_texel, in.shape_a.xy, in.meta_.w);
}

fn plain_composite(in: VsOut, cov: f32) -> vec4<f32> {
    let flags = (in.meta_.w >> 24u) & 0xffu;
    let tspace = select(SPACE_LINEAR, SPACE_SRGB, (flags & FLAG_TEX_SRGB) != 0u);
    let coord = vec2<i32>(floor(in.device - instances[in.instance].grad.xy));
    return move_space(read_composite_source(coord), tspace, globals.space) * cov;
}

// full-fragment
fn fs_full(fragment: VsOut) -> vec4<f32> {
    // A device-space quad paints, clips and samples at its pixel, never at
    // a point interpolated across the quad.
    let in = device_quad_pixel(fragment);
    // The constants every fragment needs arrive as flat varyings; the
    // storage array is read only for kind-specific fields (inner, clip,
    // mask, gradient data).
    let i = in.instance;
    let s = Shape(in.shape_a.xy, in.shape_a.z, in.shape_a.w, in.shape_radii);
    let m = array<vec4<f32>, 2>(in.affine0, in.affine1);
    let flags = (in.meta_.w >> 24u) & 0xffu;
    var cov: f32;
    // Where the draw coverage is a signed-distance evaluation, its
    // boundary half-planes join the clip's and the joint draw∩clip pixel
    // area replaces the coverage product (#2933). Coverages without a
    // signed-distance edge — path cells, the shadow kernel — keep the
    // product.
    var planes: JointPlanes;
    var nplanes = 0u;
    var joint = true;
    switch in.meta_.x {
        case KIND_STROKE_OFFSET: {
            let outer = shape_eval(s, in.local, m, false);
            cov = outer.cov;
            planes[nplanes] = outer.planes.p[0];
            nplanes += 1u;
            if outer.planes.n == 2u {
                planes[nplanes] = outer.planes.p[1];
                nplanes += 1u;
            }
            if (flags & FLAG_HAS_INNER) != 0u {
                let inner = shape_eval(instances[i].inner, in.local, m, false);
                cov -= inner.cov;
                // Outside the inner shape. A corner's outside is a union
                // of half-planes — not the intersection a polygon clip
                // expresses — so only a single-plane inner joins.
                if inner.planes.n == 1u {
                    planes[nplanes] = -inner.planes.p[0];
                    nplanes += 1u;
                } else {
                    joint = false;
                }
            }
        }
        case KIND_STROKE_DIST: {
            let sample = sdf_sample(s, in.local, false);
            let d = sample.distance;
            let g = sample.gradient;
            let v = device_grad_vec(m, g.xy);
            let scale = device_grad_scale(m);
            let ramp = g.w > 0.0;
            let hw = in.params.x;
            cov = coverage_dir(d - hw, v, scale, ramp, select(g.z + hw, 0.0, g.z <= 0.0))
                - coverage_dir(d + hw, v, scale, ramp, select(max(g.z - hw, 0.0), 0.0, g.z <= 0.0));
            let det = m[0].x * m[0].w - m[0].y * m[0].z;
            let dv = v / det;
            planes[0] = vec3<f32>(d - hw, dv);
            planes[1] = vec3<f32>(-d - hw, -dv);
            nplanes = 2u;
        }
        case KIND_SHADOW: {
            let sigma = in.params.x;
            if sigma < 0.25 {
                let se = shape_eval(s, in.local, m, false);
                cov = se.cov;
                planes[nplanes] = se.planes.p[0];
                nplanes += 1u;
                if se.planes.n == 2u {
                    planes[nplanes] = se.planes.p[1];
                    nplanes += 1u;
                }
            } else {
                cov = shadow(s, in.local, sigma);
                joint = false;
            }
        }
        case KIND_GLYPH: {
            cov = glyph_coverage(in);
            joint = false;
        }
        case KIND_SPAN: {
            cov = 1.0;
        }
        default: {
            let de = shape_eval(s, in.local, m, false);
            cov = de.cov;
            planes[nplanes] = de.planes.p[0];
            nplanes += 1u;
            if de.planes.n == 2u {
                planes[nplanes] = de.planes.p[1];
                nplanes += 1u;
            }
        }
    }
    if joint && (flags & FLAG_HAS_CLIP) != 0u {
        let cp = clip_planes(in);
        for (var k = 0u; k < cp.n; k = k + 1u) {
            planes[nplanes + k] = cp.p[k];
        }
        cov = planes_coverage(planes, nplanes + cp.n) * mask_coverage(in);
    } else {
        cov *= clip_mask_coverage(in);
    }
    // Coverage before the opacity multiply is the composite's clip coverage:
    // the destructive Porter-Duff branch antialiases the clip edge between
    // the backdrop and the blended result.
    let inside_cov = clamp(cov, 0.0, 1.0);
    cov = inside_cov * in.params.y;
    // generic-composite
    // A PAINT_TEXTURE instance samples a target texture: a plain member
    // sample (mode 0, no FLAG_BLEND_SRC) converts the texel into the
    // pass's space and blends over by fixed function; a composite blends
    // in the source texture's space — the mode in meta_.w bits 16-23,
    // Normal when FLAG_BLEND_SRC only marks a space crossing — reading
    // the backdrop explicitly (the pass runs the Replace pipeline).
    if in.meta_.y == PAINT_TEXTURE {
        let mode = (in.meta_.w >> 16u) & 0xffu;
        let tspace = select(SPACE_LINEAR, SPACE_SRGB, (flags & FLAG_TEX_SRGB) != 0u);
        let coord = vec2<i32>(floor(in.device - instances[i].grad.xy));
        if mode == 0u && (flags & FLAG_BLEND_SRC) == 0u {
            return plain_composite(in, cov);
        }
        let cb = read_composite_backdrop(coord);
        if blend_is_destructive(mode) {
            // Destructive operators composite over the whole region: a
            // transparent source still writes over the backdrop.
            let cs = read_composite_source(coord) * in.params.y;
            return mix(cb, composite_space(mode, tspace, cb, cs), inside_cov);
        }
        let cs = read_composite_source(coord) * cov;
        return composite_space(mode, tspace, cb, cs);
    }
    if in.meta_.y == PAINT_BACKDROP {
        // The bound capture stores its own space (FLAG_TEX_SRGB): the
        // effect evaluates on it and the result lands in globals.space.
        let tspace = select(SPACE_LINEAR, SPACE_SRGB, (flags & FLAG_TEX_SRGB) != 0u);
        if (flags & FLAG_BLEND_SRC) != 0u {
            // The member blends in its group's space, unlike the pass's
            // storage (two spaces exist, so it is the other one): the
            // canvas comes from the backdrop copy at device origin
            // `color.yz`, the sample source-over in the member space,
            // the result written verbatim. An uncovered pixel keeps the
            // canvas untouched.
            let coord = vec2<i32>(floor(in.device - instances[i].color.yz));
            let cb = read_composite_backdrop(coord);
            if cov <= 0.0 {
                return cb;
            }
            let space = select(SPACE_SRGB, SPACE_LINEAR, globals.space == SPACE_SRGB);
            let cs = move_space(paint_backdrop(i, in.device) * cov, tspace, space);
            let over = cs + move_space(cb, globals.space, space) * (1.0 - cs.a);
            return move_space(over, space, globals.space);
        }
        return move_space(paint_backdrop(i, in.device) * cov, tspace, globals.space);
    }
    // generic-composite
    return move_space(paint(i, in.meta_, in.color, in.local, in.device) * cov, SPACE_LINEAR, globals.space);
}

// full-fragment

// Blend-mode compositing shared by the engine tail (`shader.wgsl`) and the
// projective composite (`projective.wgsl`): W3C Compositing and Blending
// Level 1 on premultiplied pixels. `build.rs` concatenates it after the
// module's own tail; it is not a module on its own.

// The isolated-plane composite: the source texel is already in blend
// space `s`; the backdrop converts in and the blended result converts
// back to the pass's storage space.
fn composite_space(mode: u32, s: u32, cb: vec4<f32>, cs: vec4<f32>) -> vec4<f32> {
    return move_space(blend_color(mode, move_space(cb, globals.space, s), cs), s, globals.space);
}

// W3C Compositing and Blending Level 1, a literal port of
// oracle/src/blend.rs. Premultiplied inputs and output.
//
// Extension over the W3C text (#2908): the four non-separable modes
// (Hue, Saturation, Color, Luminosity) evaluate B on a shared affine
// domain covering both straight colours instead of fixed SDR [0,1], so
// extended-range and negative channels blend through the same formulas
// rather than clamping. See blend_color.

fn lum(c: vec3<f32>) -> f32 {
    return 0.3 * c.x + 0.59 * c.y + 0.11 * c.z;
}

fn sat(c: vec3<f32>) -> f32 {
    return max(c.x, max(c.y, c.z)) - min(c.x, min(c.y, c.z));
}

fn clip_color(c_in: vec3<f32>) -> vec3<f32> {
    var c = c_in;
    let l = lum(c);
    let n = min(c.x, min(c.y, c.z));
    let x = max(c.x, max(c.y, c.z));
    if n < 0.0 {
        c = l + (c - l) * l / (l - n);
    }
    if x > 1.0 {
        c = l + (c - l) * (1.0 - l) / (x - l);
    }
    return c;
}

fn set_lum(c: vec3<f32>, l: f32) -> vec3<f32> {
    let d = l - lum(c);
    return clip_color(c + d);
}

fn set_sat(c: vec3<f32>, s: f32) -> vec3<f32> {
    var mn = 0;
    var mx = 0;
    for (var i = 1; i < 3; i += 1) {
        if c[i] < c[mn] {
            mn = i;
        }
        if c[i] > c[mx] {
            mx = i;
        }
    }
    let imid = 3 - mn - mx;
    var out = vec3<f32>(0.0);
    if c[mx] > c[mn] {
        out[imid] = (c[imid] - c[mn]) * s / (c[mx] - c[mn]);
        out[mx] = s;
    }
    return out;
}

// The Porter-Duff operators whose transparent source replaces the
// destination rather than leaving it unchanged (codes per blend_code).
fn blend_is_destructive(mode: u32) -> bool {
    return mode == 16u || mode == 17u || mode == 20u || mode == 21u || mode == 22u || mode == 25u;
}

// B(Cb, Cs) for one channel pair, separable modes; non-separable modes and
// Porter-Duff operators are handled in blend_color, not here.
fn blend_channel(mode: u32, cb: f32, cs: f32) -> f32 {
    switch mode {
        case 1u: { return cb * cs; }                                 // Multiply
        case 2u: { return cb + cs - cb * cs; }                       // Screen
        case 3u: {                                                   // Overlay
            if cb <= 0.5 { return 2.0 * cb * cs; }
            return 1.0 - 2.0 * (1.0 - cb) * (1.0 - cs);
        }
        case 4u: { return min(cb, cs); }                             // Darken
        case 5u: { return max(cb, cs); }                             // Lighten
        case 6u: {                                                   // ColorDodge
            if cs >= 1.0 { return 1.0; }
            return min(cb / (1.0 - cs), 1.0);
        }
        case 7u: {                                                   // ColorBurn
            if cs <= 0.0 { return 0.0; }
            return 1.0 - min((1.0 - cb) / cs, 1.0);
        }
        case 8u: {                                                   // HardLight
            if cs <= 0.5 { return 2.0 * cb * cs; }
            return 1.0 - 2.0 * (1.0 - cb) * (1.0 - cs);
        }
        case 9u: {                                                   // SoftLight
            if cs <= 0.5 {
                return cb - (1.0 - 2.0 * cs) * cb * (1.0 - cb);
            }
            var d: f32;
            if cb <= 0.25 {
                d = ((16.0 * cb - 12.0) * cb + 4.0) * cb;
            } else {
                d = sqrt(cb);
            }
            return cb + (2.0 * cs - 1.0) * (d - cb);
        }
        case 10u: { return abs(cb - cs); }                           // Difference
        case 11u: { return cb + cs - 2.0 * cb * cs; }                // Exclusion
        default: { return cs; }
    }
}

// Porter-Duff: co = αs·Fa·Cs + αb·Fb·Cb in premultiplied form.
fn porter_duff(fa: f32, fb: f32, cb: vec4<f32>, cs: vec4<f32>) -> vec4<f32> {
    return fa * cs + fb * cb;
}

// blend(mode, cb, cs): premultiplied backdrop and source, composited
// premultiplied output — oracle blend().
fn blend_color(mode: u32, cb: vec4<f32>, cs: vec4<f32>) -> vec4<f32> {
    let ab = cb.a;
    let as_ = cs.a;
    switch mode {
        case 16u: { return vec4<f32>(0.0); }                              // Clear
        case 17u: { return cs; }                                          // Src
        case 18u: { return cb; }                                          // Dst
        case 19u: { return porter_duff(1.0 - ab, 1.0, cb, cs); }           // DestOver
        case 20u: { return porter_duff(ab, 0.0, cb, cs); }                 // SrcIn
        case 21u: { return porter_duff(0.0, as_, cb, cs); }                // DestIn
        case 22u: { return porter_duff(1.0 - ab, 0.0, cb, cs); }           // SrcOut
        case 23u: { return porter_duff(0.0, 1.0 - as_, cb, cs); }          // DestOut
        case 24u: { return porter_duff(ab, 1.0 - as_, cb, cs); }           // SrcAtop
        case 25u: { return porter_duff(1.0 - ab, as_, cb, cs); }           // DestAtop
        case 26u: { return porter_duff(1.0 - ab, 1.0 - as_, cb, cs); }     // Xor
        case 27u: { return vec4<f32>(cs.rgb + cb.rgb, min(as_ + ab, 1.0)); } // PlusLighter
        default: {}
    }
    if as_ == 0.0 {
        return cb;
    }
    var ub = vec3<f32>(0.0);
    if ab > 0.0 {
        ub = cb.rgb / ab;
    }
    let us = cs.rgb / as_;
    // #2908: the non-separable modes share one affine domain covering
    // both straight colours — lo = min(0, all six channels), hi = max(1,
    // all six), so the domain always contains [0,1]. When the domain is
    // extended, both colours normalize through scale = max(-lo, hi) as
    // (c/scale - lo/scale) / (hi/scale - lo/scale) — the same affine map
    // as (c - lo)/(hi - lo) with every intermediate bounded in magnitude
    // by 2, so even ±f32::MAX channels stay finite where the direct
    // width hi - lo would overflow. nb/ns are the colours the SDR formulas below see;
    // a pure-SDR pair hits the identity domain and keeps the exact
    // original arithmetic. Since lum and sat are affine-covariant the
    // modes keep their semantics; the blend result maps back through
    // lo·(1-B) + hi·B after the switch (the convex combination
    // lo + (hi-lo)·B written with opposite-sign terms so no intermediate
    // can overflow), and the source-over tail still uses the
    // unnormalized us.
    var nb = ub;
    var ns = us;
    var lo = 0.0;
    var hi = 1.0;
    var normalized = false;
    switch mode {
        case 12u, 13u, 14u, 15u: {
            for (var i = 0; i < 3; i += 1) {
                lo = min(lo, min(ub[i], us[i]));
                hi = max(hi, max(ub[i], us[i]));
            }
            if lo < 0.0 || hi > 1.0 {
                let scale = max(-lo, hi);
                let low_scaled = lo / scale;
                let width_scaled = hi / scale - low_scaled;
                nb = (ub / scale - vec3<f32>(low_scaled)) / width_scaled;
                ns = (us / scale - vec3<f32>(low_scaled)) / width_scaled;
                normalized = true;
            }
        }
        default: {}
    }
    var b: vec3<f32>;
    switch mode {
        case 12u: { b = set_lum(set_sat(ns, sat(nb)), lum(nb)); }          // Hue
        case 13u: { b = set_lum(set_sat(nb, sat(ns)), lum(nb)); }          // Saturation
        case 14u: { b = set_lum(ns, lum(nb)); }                            // Color
        case 15u: { b = set_lum(nb, lum(ns)); }                            // Luminosity
        default: {
            b = vec3<f32>(
                blend_channel(mode, ub.x, us.x),
                blend_channel(mode, ub.y, us.y),
                blend_channel(mode, ub.z, us.z),
            );
        }
    }
    if normalized {
        b = fma(vec3<f32>(hi), b, lo * (vec3<f32>(1.0) - b));
    }
    // Cr = (1-αb)·Cs + αb·B(Cb,Cs); premultiplied: αs·Cr + (1-αs)·Cb.
    var out: vec4<f32>;
    for (var i = 0; i < 3; i += 1) {
        let cr = (1.0 - ab) * us[i] + ab * b[i];
        out[i] = as_ * cr + (1.0 - as_) * cb[i];
    }
    out.a = as_ + ab * (1.0 - as_);
    return out;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    return fs_full(in);
}

